\label{lem:bo-zong-aux-lemma}
  Let $x \in X$ be given and consider a fixed~$i \in [m]$.
  Then, $x$ satisfies the $i$-th coupling constraint
  in~\eqref{eq:coupling-constrs-comp-wise} if and only if there exist
  $\bar{y}$ and
  \begin{equation*}
    y^i \in \operatorname*{arg\,min} \left\{B_{i\cdot} y\defsepDy \geq b - Cx, \, f^\top y
      \leq f^\top \bar{y}\right\}
  \end{equation*}
  that satisfy
  \begin{equation*}
    D \bar{y} \geq b - Cx,
    \quad
    B_{i\cdot} y^i \geq a_i - A_{i\cdot} x.
  \end{equation*}

\label{cor:bo-zong-aux-lemma}

  A given $x \in X$ satisfies all coupling constraints
  in~\eqref{eq:coupling-constrs-comp-wise} if and only if there exist
  $\bar{y}$ satisfying $D \bar{y} \geq b - Cx$ and, for every~$i \in [m]$,
  \begin{equation*}
    y^i \in \operatorname*{arg\,min} \left\{B_{i\cdot} y\defsepDy \geq b - Cx, \, f^\top y
      \leq f^\top \bar{y}\right\}
  \end{equation*}
  with
  \begin{equation*}
    B_{i\cdot} y^i \geq a_i - A_{i\cdot} x.
  \end{equation*}

\label{thm:pwcc-to-owcc}
  Let $\mathcal{S}$ be the set of globally optimal solutions to the
  pessimistic bilevel problem~\eqref{eq:bilevel-press-w-ccs} with
  coupling constraints, i.e., to the problem
  \begin{subequations}
    \label{eq:bo-zeng-orig-problem}
    \begin{align}
      \min_{x \in X} \quad
      & F_{\mathrm{pc}}(x) = c^\top x
      \\
      \text{s.t.} \quad
      & Ax + By \geq a \quad \text{for all } y \in S(x).
    \end{align}
  \end{subequations}
  Moreover, let $\hat{\mathcal{S}}$ be the set of globally
  optimal solutions to the optimistic bilevel problem
  \begin{equation*}
    \min_{(x, \bar{y}) \in \tilde{X}} \
    c^\top x + \min_y \left\{0\defsepy \in \hat{S}(x, \bar{y}), \,
      B_{i\cdot} y^i \geq a_i - A_{i\cdot} x \text{ for all } i \in [m]\right\},
  \end{equation*}
  with $\tilde{X} = \{(x, \bar{y})\defsepx \in X, D \bar{y} \geq b -
    Cx\}$ and with $\hat{S}(x, \bar{y})$ being the set of optimal
  solutions to the lower-level problem
  \begin{align*}
    \min_y \quad
    & \sum_{i=1}^m B_{i\cdot} y^i
    \\
    \text{s.t.} \quad
    & Dy^i \geq b - Cx
      \quad \text{for all } i \in [m],
    \\
    & f^\top y^i \leq f^\top \bar{y}
      \quad \text{for all } i \in [m].
  \end{align*}
  Then,
  \begin{equation*}
    \mathcal{S} = \operatorname{proj}_x(\hat{\mathcal{S}})
  \end{equation*}
  holds and the optimal objective function values coincide.

\label{lemma:henke-penalized-eps-version}
  There is a polynomial-sized parameter $\kappa > 0$ so that
  Problem~\eqref{eq:bilevel-epsilon} has the same set of globally
  optimal solutions as the optimistic bilevel problem
  \begin{equation}
    \label{eq:bilevel-epsilon-wo-coupling}
    \min_{(x,\bar{y})\in \tilde{X}} \quad F_{\mathrm{o\kappa}}(x,\bar{y})
    \mathrel{{\mathop:}{=}} c^\top x + d^\top \bar{y} + \min_{y,\varepsilon}
    \left\{\kappa \varepsilon\colon(y,\varepsilon) \in \tilde S(x, \bar{y}) \right\}
  \end{equation}
  without coupling constraints.
  Here, we again use $\tilde{X} = \{(x, \bar{y})\defsepx \in X, D
    \bar{y} \ge b - Cx \}$ and $\tilde S(x, \bar{y})$ is the set of
  optimal solutions of~\eqref{eq:bilevel-epsilon-lower}.

\label{prop:opt-wo-cc-to-pess-wo-cc-for-epsilon-problem}
  For any~$\kappa$, the optimistic bilevel
  problem~\eqref{eq:bilevel-epsilon-wo-coupling} without
  coupling constraints and its pessimistic version
  \begin{equation}
    \label{eq:bilevel-epsilon-wo-coupling-pessimistic}
    \min_{(x,\bar{y})\in \tilde{X}} \quad F_{\mathrm{p\kappa}}(x,\bar{y})
    \mathrel{{\mathop:}{=}} c^\top x + d^\top \bar{y}
    + \max_{y,\varepsilon} \left\{\kappa \varepsilon\colon
      (y,\varepsilon) \in \tilde S(x, \bar{y}) \right\}
  \end{equation}
  have the same set of feasible and globally optimal solutions.
